import {searchLocationPairs,PAIR_METHOD} from './planetary-search.js';
import {escapeHTML as esc,icon} from './icons.js';
import {createPairConnector} from './pair-connector.js';
const label=site=>Math.abs(site.lat).toFixed(3)+'°'+(site.lat<0?'S':'N')+' · '+Math.abs(site.lon).toFixed(3)+'°'+(site.lon<0?'W':'E');
const number=(n,d=1)=>Number(n).toLocaleString('en-US',{maximumFractionDigits:d});
export function createPairDashboard(options){
 const workspace=document.querySelector('.explore-workspace'),results=document.createElement('section'),panel=document.createElement('aside');
 results.className='pair-results';results.id='pair-results';results.setAttribute('aria-label','Matching location pairs');document.querySelector('.candidate-tray').after(results);
 panel.className='panel selected-match';panel.id='selected-match';panel.setAttribute('aria-label','Selected location pair');workspace.append(panel);
 const peeks=document.createElement('div');peeks.className='planet-peeks';peeks.innerHTML='<button data-pair-body="moon" aria-label="View Moon"><img src="assets/official-moon.jpg" alt="Moon agency mosaic"><span>Moon</span></button><button data-pair-body="mars" aria-label="View Mars"><img src="assets/official-mars.jpg" alt="Mars agency mosaic"><span>Mars</span></button>';
 document.querySelector('#globe-stage').append(peeks);peeks.querySelectorAll('button').forEach(b=>b.onclick=()=>options.onBody(b.dataset.pairBody));
 let pairs=[],selectedId=null,coverage=null,running=false,mode='automatic',runId=0;
 const connector=createPairConnector({stage:document.querySelector('#globe-stage'),peeks,getPair:()=>pairs.find(p=>p.id===selectedId),projectSite:site=>options.projectSite?.(site),isEnabled:()=>mode==='automatic'&&!document.querySelector('#explore-view').classList.contains('hidden')});
 function selectPair(id,{compare=false}={}){const p=pairs.find(p=>p.id===id);if(!p)return;selectedId=id;options.onSelectPair(p,{compare});render();}
 function empty(){panel.innerHTML='<div class="panel-title"><h2>Selected match</h2><span class="status-pill">EVIDENCE</span></div><div class="pair-empty">'+icon('globe')+'<h3>Discover a location pair</h3><p>Search real Earth, Moon and Mars elevation data. Select a result to inspect both locations and their measured terrain.</p></div><div class="pair-source-note"><strong>Real numeric terrain</strong><p>Earth elevation tiles · NASA MOLA · NASA LOLA</p><p>32 km areas · 2 km comparison grid · 4 km slope baseline</p></div>';}
 function render(){
  connector.update();
  results.innerHTML='<div class="tray-heading"><h2>Matching location pairs</h2><span>'+ (running?'Searching…':pairs.length+' pairs')+'</span></div>'+(coverage?'<p class="pair-coverage">'+number(coverage.earthCompleted,0)+' / '+number(coverage.earthPlanned,0)+' Earth areas loaded · '+Object.entries(coverage.planetaryIndexed||{}).map(([b,n])=>number(n,0)+' '+b+' areas indexed').join(' · ')+'<br>'+number(coverage.earthExcluded,0)+' coverage exclusions · '+number(coverage.earthFailed,0)+' Earth failures · '+number(coverage.pairFailures?.length||0,0)+' planetary failures'+(coverage.cancelled?' · Cancelled, partial results':'')+' <button class="text-link" id="inspect-pair-coverage">Inspect search record ↗</button></p>':'<p class="pair-coverage">Run Automatic Search to find coordinate-derived pairs. Reference sites remain available in Manual search.</p>')+
   (pairs.length?'<div class="pair-list">'+pairs.map((p,i)=>'<button class="pair-row '+(p.id===selectedId?'selected':'')+'" data-pair="'+esc(p.id)+'" aria-pressed="'+(p.id===selectedId)+'"><span class="pair-rank">'+(i+1)+'</span><img src="'+options.thumbnail(p.earth.site)+'" alt="Earth DEM shaded relief"><span class="pair-area"><strong>'+esc(p.earth.site.name)+'</strong><small>'+esc(p.earth.site.country)+' · '+label(p.earth.site)+'</small></span><span class="pair-arrow">↔</span><img src="'+options.thumbnail(p.target.site)+'" alt="'+p.target.site.country+' DEM shaded relief"><span class="pair-area"><strong>'+esc(p.target.site.country+' terrain area')+'</strong><small>'+label(p.target.site)+'</small></span><span class="pair-index">'+number(p.comparison.score)+'<small>/ 100 terrain index</small></span><span class="pair-open">View evidence ↗</span></button>').join('')+'</div><p class="pair-footnote">Terrain index is a heuristic, not confidence or mission suitability. Prior analog use is unverified. Thumbnails are DEM shaded relief, not surface photographs.</p>':'<div class="pair-results-empty">'+(running?'Reading source data and comparing terrain. Completed pairs will appear here.':coverage?'No comparable pair found in this sample. Inspect the search record, then try another condition or region.':'No search results yet. Choose Moon, Mars or Both, then find matching locations.')+'</div>');
  results.querySelectorAll('[data-pair]').forEach(button=>button.onclick=()=>selectPair(button.dataset.pair));results.querySelector('#inspect-pair-coverage')?.addEventListener('click',()=>options.onCoverage(coverage));
  const p=pairs.find(p=>p.id===selectedId);if(!p){empty();if(coverage&&!running){panel.querySelector('.pair-empty h3').textContent='No comparable pair in this sample';panel.querySelector('.pair-empty p').textContent='Review the search record for exclusions or unavailable data, then try a different terrain condition, Earth region or sample size.';}return;}const a=p.comparison.earthStats,b=p.comparison.targetStats;
  const bar=(title,av,bv,unit)=>{const max=Math.max(av,bv,1);return'<div class="pair-measure"><h4>'+title+'</h4><div><span class="earth-key">Earth</span><i style="--bar:'+Math.max(1,av/max*100)+'%"></i><strong>'+number(av,unit==='°'?2:0)+unit+'</strong></div><div><span class="planet-key">'+p.target.site.country+'</span><i style="--bar:'+Math.max(1,bv/max*100)+'%"></i><strong>'+number(bv,unit==='°'?2:0)+unit+'</strong></div></div>';};
  panel.innerHTML='<div class="panel-title"><h2>Selected match</h2><span class="status-pill">REAL DEM DATA</span></div><div class="pair-images"><figure><img src="'+options.thumbnail(p.earth.site)+'" alt="Earth elevation hillshade"><figcaption>EARTH · DEM SHADED RELIEF</figcaption></figure><figure><img src="'+options.thumbnail(p.target.site)+'" alt="Planetary elevation hillshade"><figcaption>'+p.target.site.country.toUpperCase()+' · DEM SHADED RELIEF</figcaption></figure></div><div class="pair-selected-title"><h3>'+esc(p.earth.site.name)+'</h3><p>'+label(p.earth.site)+'</p><span>↕</span><h3>'+p.target.site.country+' terrain area</h3><p>'+label(p.target.site)+'</p></div><section class="pair-why"><h3>Why this pair?</h3><p>Slope-distribution distance: '+number(p.comparison.slopeDistance,3)+'; 0 means the same measured distribution.</p><p>Relative relief differs by '+number(Math.abs(a.relief-b.relief),0)+' m across equal 32 km areas.</p><strong>'+number(p.comparison.score)+' / 100 <span>terrain resemblance index</span></strong></section><section class="pair-evidence"><h3>Evidence to inspect</h3>'+bar('Mean regional slope',a.slopeMean,b.slopeMean,'°')+bar('Relative relief',a.relief,b.relief,' m')+'<p>Both: 2 km grid · 4 km slope baseline. Output spacing is not source accuracy.</p></section><div class="pair-source-note"><strong>Traceable data</strong><p>Earth · Mapzen / Tilezen mixed-source elevations<br>'+p.target.site.country+' · NASA '+(p.target.site.body==='mars'?'MOLA':'LOLA')+'</p><p>Candidate analog · prior use unverified.<br>Materials, field access and mission safety need separate evidence.</p><button class="text-link" id="pair-provenance">Inspect original source records ↗</button></div><div class="pair-actions"><button class="button button-primary" id="compare-pair">'+icon('compare')+' Compare this pair</button><button class="button button-outline" id="explore-pair">'+icon('terrain')+' Explore terrain in 3D</button></div>';
  panel.querySelector('#compare-pair').onclick=()=>selectPair(p.id,{compare:true});panel.querySelector('#explore-pair').onclick=()=>options.onExplore(p.target.site);panel.querySelector('#pair-provenance').onclick=()=>options.onProvenance(p);
 }
 function setMode(value){mode=value;document.querySelector('#explore-view').classList.toggle('pair-search-mode',value==='automatic');document.querySelector('.mission-panel').hidden=value==='automatic';panel.hidden=value!=='automatic';results.hidden=value!=='automatic';peeks.hidden=value!=='automatic';connector.update();options.onMode?.(value);requestAnimationFrame(()=>options.onResize?.());}
 async function run(settings){const id=++runId;const active=()=>id===runId;pairs=[];selectedId=null;coverage=null;running=true;render();options.onSearchStart?.();try{
  const result=await searchLocationPairs({...settings,onProgress:event=>{if(!active())return;coverage=event;settings.onProgress?.(event);},onEarth:record=>{if(active())options.onEarth(record);},onPair:pair=>{if(!active())return;options.onPlanetary(pair.target);pairs.push(pair);pairs.sort((a,b)=>b.comparison.score-a.comparison.score);if(!selectedId)selectPair(pairs[0].id);else render();}});
  if(!active())return result;coverage=result.coverage;if(pairs.length)selectPair(pairs[0].id);options.onComplete?.(result);return result;
 }catch(error){if(active()&&error.partial){coverage={...error.partial.coverage,status:'failed',error:error.message};options.onComplete?.({pairs,coverage});}throw error;}finally{if(active()){running=false;render();}}}
 function comparisonHTML(){if(!pairs.length)return '';return '<section class="panel comparison-notes all-pairs-overview"><p class="eyebrow">AUTOMATIC SEARCH RESULTS</p><h2>Compare every discovered pair</h2><p>Each row compares its own Earth and planetary areas at the same 2 km spacing. Scores are terrain heuristics; prior analog use remains unverified.</p><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Earth study area</th><th>Planetary area</th><th>Terrain index / 100</th><th>Mean slope · Earth / target</th><th>Relief · Earth / target</th><th>Evidence</th></tr></thead><tbody>'+pairs.map(p=>'<tr><td>'+esc(p.earth.site.name)+'<br>'+label(p.earth.site)+'</td><td>'+p.target.site.country+'<br>'+label(p.target.site)+'</td><td>'+number(p.comparison.score)+'</td><td>'+number(p.comparison.earthStats.slopeMean,2)+'° / '+number(p.comparison.targetStats.slopeMean,2)+'°</td><td>'+number(p.comparison.earthStats.relief,0)+' / '+number(p.comparison.targetStats.relief,0)+' m</td><td><button class="text-link" data-pair-compare="'+esc(p.id)+'">Inspect pair ↗</button></td></tr>').join('')+'</tbody></table></div></section>';}
 function report(){return coverage?'\n\n## Automatic location-pair search\n\n32 km study areas; 2 km comparison spacing; 4 km slope baselines. The planetary index is a 3° bounded sample, not every possible location. Prior analog use remains unverified.\n\n| Earth area | Earth coordinates | Planet | Planetary coordinates | Terrain index / 100 |\n| --- | --- | --- | --- | ---: |\n'+pairs.map(p=>'| '+p.earth.site.name+' | '+label(p.earth.site)+' | '+p.target.site.country+' | '+label(p.target.site)+' | '+number(p.comparison.score)+' |').join('\n')+'\n\nSearch coverage and failures:\n\n```json\n'+JSON.stringify(coverage,null,2)+'\n```\n':'';}
 render();return{run,setMode,selectPair,comparisonHTML,report,updateConnector:connector.update,get pairs(){return pairs;},get selected(){return pairs.find(p=>p.id===selectedId)||null;},get coverage(){return coverage;},get mode(){return mode;},refresh:render};
}
